-- 2026-10-15: the creator checklist, three short lines per box (checklist_json). Full guide / rules / avoid stay for briefs and the bots.
ALTER TABLE p_amb_brand ADD COLUMN checklist_json TEXT;
UPDATE p_amb_brand SET checklist_json = '{"do": [{"title": "Hands first, then talk", "text": "The patch going on in the first second."}, {"title": "Change the picture at 3 seconds", "text": "Night out, then the morning plans."}, {"title": "End on her day", "text": "Up at 7, plans happening, patch on."}], "say": ["\"For a better next day\", never \"cures hangovers\".", "\"Water resistant\", never \"waterproof\".", "The patch goes on before the night, on camera."], "skip": ["Talking to the camera while nothing happens.", "Anyone under 21, drunk, or hungover in bed.", "\"Hangxiety\", anxiety or stress claims."]}' WHERE slug = 'party-patch';
UPDATE p_amb_brand SET checklist_json = '{"do": [{"title": "Hands first, then talk", "text": "Mailer ripping, hat going on, cans in the cooler."}, {"title": "Let the print be the joke", "text": "Fill the frame with it and say its name."}, {"title": "Film your buddies", "text": "A real round, beer in hand, nobody drunk."}], "say": ["The fit is \"relaxed, dad bod approved\".", "Sizes go small to 4XL. Check the site before saying 5XL.", "Deals: only what is on the site that day."], "skip": ["Holding the polo up against a wall.", "Chugging, acting drunk, or anyone under 21 drinking.", "\"Stain-proof\", \"slimming\", or another brand''s name."]}' WHERE slug = 'grunk-dolfer';
UPDATE p_amb_brand SET checklist_json = '{"do": [{"title": "Hands first, then talk", "text": "Old belt in the bin, scissors on the strap."}, {"title": "Use it, do not describe it", "text": "Mark the ball, pull a tee, on the course."}, {"title": "Say what people think", "text": "\"$100 for a golf belt?\" Then answer it."}], "say": ["\"Patented magnetic buckle\" and \"fits up to 46 inches\".", "Gator and croc belts are embossed leather, not real skin.", "Offers: only what is live on the site that day."], "skip": ["Holding the belt up and naming features.", "\"It makes you play better\" (an obvious joke is fine).", "Review counts, star ratings or customer numbers."]}' WHERE slug = 'dartee';
UPDATE p_amb_brand SET checklist_json = '{"do": [{"title": "Flip it in the first 3 seconds", "text": "One move, no cut."}, {"title": "Wear it in both worlds", "text": "Camo at the lease, black at the office."}, {"title": "Show one detail", "text": "The chapstick pocket, the lens swatch, the tag scan."}], "say": ["\"Made by a hunting brand\" and \"two sides\".", "Show the flip before you say \"reversible\".", "Offers: only what is live on the site that day."], "skip": ["A jacket on a hanger with a feature list.", "Making fun of city people or country people.", "Warmth or waterproof claims, or weapons in frame."]}' WHERE slug = 'hiden';
UPDATE p_amb_brand SET checklist_json = '{"do": [{"title": "Wear it before you talk", "text": "Face in frame, gold catching the light."}, {"title": "Show water or sweat", "text": "Shower, gym or pillow, and it still shines."}, {"title": "Name the piece", "text": "Say its name and its price from the site."}], "say": ["\"18K gold PVD\", never \"solid gold\" or \"gold plated\".", "\"Water resistant\", not \"waterproof\".", "The deal, exactly: \"Pick any 4 pieces for $150\"."], "skip": ["The piece on a table with nobody wearing it.", "Vinegar, magnet or acid \"real gold\" tests.", "A haul of pieces with no single hero."]}' WHERE slug = 'ice-and-gold';
